def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < n and line[i] != ',':
                            # Invalid: closing quote not followed by comma or end
                            return None
                        if i < n:
                            i += 1  # Skip the comma
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field - runs to next comma
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

